CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'awaiting_payment' CHECK(status IN ('awaiting_payment','payment_confirmed','shipped','completed','cancelled')), customer_name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT, shipping_address TEXT NOT NULL, items_json TEXT NOT NULL, subtotal_cents INTEGER NOT NULL CHECK(subtotal_cents>=0), discount_cents INTEGER NOT NULL CHECK(discount_cents>=0), shipping_cents INTEGER NOT NULL CHECK(shipping_cents>=0), total_cents INTEGER NOT NULL CHECK(total_cents>=0), coupon TEXT, payment_method TEXT NOT NULL CHECK(payment_method IN ('venmo','cashapp')), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, first_viewed_at TEXT);
CREATE INDEX IF NOT EXISTS orders_status_date ON orders(status,created_at);
CREATE TABLE IF NOT EXISTS order_events (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id TEXT NOT NULL REFERENCES orders(id), status TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX IF NOT EXISTS orders_unread ON orders(first_viewed_at,created_at);
